CREATE OR REPLACE FUNCTION public.tms_reliability_selftest() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; k1 text; k2 text; ck text; output jsonb:='[]'; result jsonb; docxml text; saved_claims text; BEGIN SELECT p.id INTO uid FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.id WHERE p.ativo AND ur.role='admin' LIMIT 1; IF uid IS NULL THEN RETURN jsonb_build_object('status','blocked','reason','No active administrator'); END IF; saved_claims:=current_setting('request.jwt.claims',true); k1:=repeat('9',12)||lpad(floor(random()*1e15)::bigint::text,15,'0')||repeat('1',17); k2:=left(k1,43)||'2'; ck:=left(k1,43)||'3'; BEGIN PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true); INSERT INTO public.app_records(collection,id,data) VALUES('orders','SELFTEST-'||k1,jsonb_build_object('id','SELFTEST-'||k1,'chaveNFe',k1,'numeroNFe','SELFTEST','peso',1,'valorFrete',0,'origemValor','','clienteNome','SELFTEST','costs',jsonb_build_object('execMode',''),'timeline','[]'::jsonb,'stage','aguardando_cte')),('orders','SELFTEST-'||k2,jsonb_build_object('id','SELFTEST-'||k2,'chaveNFe',k2,'numeroNFe','SELFTEST','peso',2,'valorFrete',0,'origemValor','','clienteNome','SELFTEST','costs',jsonb_build_object('execMode',''),'timeline','[]'::jsonb,'stage','aguardando_cte')); docxml:='<cteProc><CTe><infCte Id="CTe'||ck||'"><ide><nCT>SELFTEST</nCT></ide><vPrest><vTPrest>100.01</vTPrest></vPrest><infCTeNorm><infDoc><infNFe><chave>'||k1||'</chave></infNFe><infNFe><chave>'||k2||'</chave></infNFe></infDoc></infCTeNorm></infCte></CTe></cteProc>'; result:=public.tms_import_cte(docxml); IF result->>'status'<>'importado' OR result->>'conferencia'<>'pendente' THEN RAISE EXCEPTION 'CT-e import failed %',result; END IF; IF (SELECT sum((a->>'value')::numeric) FROM public.app_records, jsonb_array_elements(data->'rateio'->'allocations') a WHERE collection='cteDocuments' AND id='CTE-'||ck)<>100.01 THEN RAISE EXCEPTION 'Allocation sum failed'; END IF; IF (SELECT count(*) FROM public.app_records WHERE collection='invoices' AND data->>'cteChave'=ck)<>1 THEN RAISE EXCEPTION 'Unique invoice failed'; END IF; result:=public.tms_import_cte(docxml); IF result->>'status'<>'duplicado' THEN RAISE EXCEPTION 'Dedupe failed'; END IF; output:=output||jsonb_build_array('CT-e multi-NF: passed','Exact allocation cents: passed','Missing freight base remains pending: passed','One receivable per CT-e: passed','Repeated CT-e: passed'); BEGIN INSERT INTO public.app_records(collection,id,data) VALUES('orders','DUP-'||k1,jsonb_build_object('id','DUP-'||k1,'chaveNFe',k1)); RAISE EXCEPTION USING ERRCODE='P0003',MESSAGE='Duplicate unexpectedly allowed'; EXCEPTION WHEN raise_exception THEN output:=output||jsonb_build_array('Duplicate NF-e rejected: passed'); END; INSERT INTO public.app_records(collection,id,data) VALUES('expenses','PAY-'||ck,jsonb_build_object('id','PAY-'||ck,'valor',100,'status','prevista','movements',jsonb_build_array(jsonb_build_object('id','PAYMENT1','type','baixa','value',40,'date','2026-10-07','author','SELFTEST','reason','SELFTEST')))); UPDATE public.app_records SET data=data||jsonb_build_object('movements',jsonb_build_array(jsonb_build_object('id','PAYMENT1','type','baixa','value',40,'date','2026-10-07','author','SELFTEST','reason','SELFTEST'),jsonb_build_object('id','REVERSAL1','type','estorno','value',40,'date','2026-10-07','author','SELFTEST','reason','SELFTEST','reverses','PAYMENT1'))) WHERE collection='expenses' AND id='PAY-'||ck; output:=output||jsonb_build_array('Partial payment and reversal: passed'); BEGIN UPDATE public.app_records SET data=data||jsonb_build_object('movements','[]'::jsonb) WHERE collection='expenses' AND id='PAY-'||ck; RAISE EXCEPTION USING ERRCODE='P0003',MESSAGE='History unexpectedly removed'; EXCEPTION WHEN raise_exception THEN output:=output||jsonb_build_array('History removal rejected: passed'); END; BEGIN PERFORM public.tms_records_commit(jsonb_build_array(jsonb_build_object('collection','orders','id','SELFTEST-'||k1,'version',0,'data',jsonb_build_object('id','SELFTEST-'||k1))),'SELFTEST'); RAISE EXCEPTION USING ERRCODE='P0003',MESSAGE='Conflict unexpectedly allowed'; EXCEPTION WHEN raise_exception THEN output:=output||jsonb_build_array('Stale concurrent version rejected: passed'); END; RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Rollback successful test'; EXCEPTION WHEN no_data_found THEN NULL; END; PERFORM set_config('request.jwt.claims',coalesce(saved_claims,''),true); RETURN jsonb_build_object('status','passed','tests',output,'data_persisted',false); END $$;
REVOKE ALL ON FUNCTION public.tms_reliability_selftest() FROM PUBLIC,authenticated,anon;
GRANT EXECUTE ON FUNCTION public.tms_reliability_selftest() TO service_role;